export class IndexingError extends Error {
  constructor(
    message: string,
    readonly context: Record<string, string | number>,
    options?: { cause?: unknown },
  ) {
    super(message, options);
    this.name = "IndexingError";
  }
}

export class SearchClusterError extends Error {
  constructor(message: string, readonly statusCode: number) {
    super(message);
    this.name = "SearchClusterError";
  }
}

export function rootCause(err: unknown): unknown {
  let current = err;
  const seen = new Set<unknown>();
  while (current instanceof Error && current.cause !== undefined && !seen.has(current)) {
    seen.add(current);
    current = current.cause;
  }
  return current;
}

export function isRetryable(err: unknown): boolean {
  const root = rootCause(err);
  if (root instanceof SearchClusterError) {
    return root.statusCode === 429 || root.statusCode >= 500;
  }
  if (root instanceof Error && "code" in root) {
    const code = (root as NodeJS.ErrnoException).code;
    return code === "ECONNRESET" || code === "ETIMEDOUT";
  }
  return false;
}

import { IndexingError, SearchClusterError } from "./errors";

export interface ProductDoc { id: string; title: string; body: string; categoryId: string; }

export interface SearchClient {
  bulk(index: string, ops: object[]): Promise<{ status: number; body: any }>;
}

export interface CatalogStore {
  loadBatch(ids: string[]): Promise<ProductDoc[]>;
}

export class ProductIndexer {
  constructor(
    private readonly search: SearchClient,
    private readonly catalog: CatalogStore,
    private readonly indexName: string,
  ) {}

  async indexBatch(batchId: string, ids: string[]): Promise<number> {
    let docs: ProductDoc[];
    try {
      docs = await this.catalog.loadBatch(ids);
    } catch (err) {
      throw new IndexingError(
        `loading batch ${batchId} from catalog`,
        { batchId, size: ids.length },
        { cause: err },
      );
    }

    const ops = docs.flatMap((d) => [
      { index: { _index: this.indexName, _id: d.id } },
      { title: d.title, body: d.body, category_id: d.categoryId },
    ]);

    try {
      const res = await this.search.bulk(this.indexName, ops);
      if (res.status >= 300 || res.body?.errors) {
        throw new SearchClusterError(`bulk request rejected for index ${this.indexName}`, res.status);
      }
    } catch (err) {
      const reason = err instanceof Error ? err.message : String(err);
      throw new IndexingError(
        `writing batch ${batchId} to ${this.indexName}: ${reason}`,
        { batchId, size: docs.length, index: this.indexName },
      );
    }
    return docs.length;
  }
}

import { ProductIndexer } from "./productIndexer";
import { IndexingError, isRetryable } from "./errors";

export interface Logger {
  info(msg: string, fields?: object): void;
  error(msg: string, fields?: object): void;
}

const MAX_ATTEMPTS = 4;
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

export async function runReindexJob(
  indexer: ProductIndexer,
  batches: Array<{ id: string; productIds: string[] }>,
  log: Logger,
): Promise<{ indexed: number; failed: string[] }> {
  let indexed = 0;
  const failed: string[] = [];

  for (const batch of batches) {
    for (let attempt = 1; ; attempt++) {
      try {
        indexed += await indexer.indexBatch(batch.id, batch.productIds);
        break;
      } catch (err) {
        const retry = isRetryable(err) && attempt < MAX_ATTEMPTS;
        log.error("batch indexing failed", {
          batchId: batch.id,
          attempt,
          willRetry: retry,
          error: err instanceof Error ? err.message : String(err),
          context: err instanceof IndexingError ? err.context : undefined,
        });
        if (!retry) {
          failed.push(batch.id);
          break;
        }
        await sleep(200 * 2 ** attempt);
      }
    }
  }

  log.info("reindex finished", { indexed, failed: failed.length });
  return { indexed, failed };
}

